-- ISOLATED POSTGRES ONLY. Synthetic schema based on inspected catalog; no production data.
create schema if not exists auth; create schema if not exists private;
create role anon nologin; create role authenticated nologin;
create function auth.uid() returns uuid language sql stable as $$select nullif(current_setting('request.jwt.claim.sub',true),'')::uuid$$;
create table public.empresas(id uuid primary key,status_conta text not null default 'aprovado',bloqueado boolean not null default false);
create table public.perfis(id uuid primary key,empresa_id uuid references empresas(id),nome text,papel text,permissoes text[],ativo boolean default true);
create table public.clientes(id uuid primary key,empresa_id uuid,nome text,unique(empresa_id,id));
create table public.produtos(id uuid primary key,empresa_id uuid,nome text,preco_venda numeric,quantidade_estoque numeric,ativo boolean default true,unique(empresa_id,id));
create table public.configuracoes_empresa(empresa_id uuid primary key,permitir_venda_sem_estoque boolean default false);
create table public.configuracoes_fiscais(empresa_id uuid primary key,emite_nota_fiscal boolean default true);
create table public.contadores_venda(empresa_id uuid primary key,ultimo_numero bigint);
create table public.caixas(id uuid primary key default gen_random_uuid(),empresa_id uuid,tipo_caixa text,numero integer,status text default 'aberto',aberto_em timestamptz default now(),aberto_por uuid,aberto_por_nome text,valor_inicial numeric default 0,fechado_em timestamptz,fechado_por uuid,fechado_por_nome text,fechamento_resumo jsonb,unique(empresa_id,id));
create table public.vendas(id uuid primary key default gen_random_uuid(),empresa_id uuid,numero_venda bigint,cliente_id uuid,forma_pagamento text,total numeric,criado_por uuid,criado_em timestamptz default now(),tipo text,cancelada_em timestamptz,caixa_id uuid,cpf_nota text,pdv_movel_dummy text,unique(empresa_id,id),unique(empresa_id,numero_venda),foreign key(empresa_id,caixa_id) references caixas(empresa_id,id));
create table public.itens_venda(id bigint generated always as identity primary key,empresa_id uuid,venda_id uuid,produto_id uuid,quantidade numeric not null check(quantidade>0),preco_unitario numeric not null check(preco_unitario>=0),subtotal numeric generated always as(round(quantidade*preco_unitario,2)) stored,pacote_cliente_id uuid,foreign key(empresa_id,venda_id) references vendas(empresa_id,id));
create table public.vendas_pagamentos(id uuid primary key default gen_random_uuid(),empresa_id uuid,venda_id uuid,forma_pagamento text,valor numeric not null check(valor>0),ordem integer,criado_por uuid,criado_em timestamptz default now(),caixa_id uuid,unique(empresa_id,venda_id,ordem),foreign key(empresa_id,venda_id) references vendas(empresa_id,id));
create table public.contas_receber(id uuid primary key default gen_random_uuid(),empresa_id uuid,cliente_id uuid,venda_id uuid,origem text,valor_original numeric,saldo_aberto numeric,vencimento date,criado_por uuid,unique(empresa_id,venda_id,origem));
create table public.pacotes_clientes(id uuid,empresa_id uuid,produto_id uuid,sessoes_usadas integer,sessoes_totais integer);
create table public.pacote_usos(empresa_id uuid,pacote_id uuid);
create table public.documentos_fiscais(empresa_id uuid,venda_id uuid,status text,chave_acesso text);
create table private.taxas_pagamentos(empresa_id uuid,venda_id uuid);
create function private.empresa_tem_modulo(text) returns boolean language sql as $$select false$$;
create function private.cpf_valido(text) returns boolean language sql as $$select false$$;
create function private.produtos_exigir_ativos(e uuid,ids uuid[]) returns void language plpgsql as $$begin if exists(select 1 from public.produtos where empresa_id=e and id=any(ids) and not ativo) then raise exception 'Produto inativo'; end if; end$$;
create function private.caixa_nome_usuario() returns text language sql as $$select nome from public.perfis where id=auth.uid()$$;
create function private.pdv_hoje() returns date language sql as $$select (now() at time zone 'America/Sao_Paulo')::date$$;
create function private.ultimo_dia_do_mes(date) returns date language sql as $$select (date_trunc('month',$1)+interval '1 month - 1 day')::date$$;
create function public.taxas_pagamento_obter() returns jsonb language sql as $$select '{"id":null,"ativo":false,"regras":[]}'::jsonb$$;
create table private.taxas_chamadas(pagamento uuid);
create function private.taxas_registrar(text,uuid,jsonb) returns void language sql as $$insert into private.taxas_chamadas values($2)$$;
